import { chromium } from 'playwright';

const URL = process.env.APP_URL ?? 'http://localhost:5180/';
const browser = await chromium.launch();
const context = await browser.newContext({ viewport: { width: 900, height: 620 } });
const page = await context.newPage();

const errors = [];
page.on('console', (msg) => { if (msg.type() === 'error' || msg.type() === 'warning') errors.push(`[${msg.type()}] ${msg.text()}`); });
page.on('pageerror', (err) => errors.push(`[pageerror] ${err.message}`));

const state = () => page.evaluate(() => ({
  htmlLang: document.documentElement.lang,
  title: document.title,
  body: document.body.innerText,
  checked: [...document.querySelectorAll('.segmented-radio-group input:checked')].map((i) => i.value),
}));

const results = [];
const check = (name, ok, extra = '') => results.push(`${ok ? 'PASS' : 'FAIL'} ${name}${extra ? ' — ' + extra : ''}`);

await page.goto(URL, { waitUntil: 'networkidle' });
await page.waitForSelector('text=Language switcher');
let s = await state();
check('default is English', s.htmlLang === 'en' && s.body.includes('Language switcher') && s.title === 'Gravity UI eval', `lang=${s.htmlLang} title=${s.title}`);
check('English option checked by default', s.checked.join() === 'en', s.checked.join());

await page.getByText('Русский', { exact: true }).click();
await page.waitForSelector('text=Переключение языка');
s = await state();
check('switch to Russian updates text', s.body.includes('Переключение языка') && s.body.includes('Текущее значение: 0') && !s.body.includes('Language switcher'));
check('Russian updates html lang and title', s.htmlLang === 'ru' && s.title === 'Gravity UI: проверка', `lang=${s.htmlLang} title=${s.title}`);
check('Russian option checked', s.checked.join() === 'ru', s.checked.join());

await page.getByRole('button', { name: 'Увеличить' }).click();
await page.getByRole('button', { name: 'Увеличить' }).click();
s = await state();
check('counter interpolation in Russian keeps state', s.body.includes('Текущее значение: 2'));

await page.reload({ waitUntil: 'networkidle' });
await page.waitForSelector('text=Переключение языка');
s = await state();
check('Russian persists after reload', s.htmlLang === 'ru' && s.body.includes('Переключение языка'));

await page.screenshot({ path: '/tmp/verify/ru.png', fullPage: true });

await page.getByText('English', { exact: true }).click();
await page.waitForSelector('text=Language switcher');
s = await state();
check('switch back to English', s.htmlLang === 'en' && s.body.includes('Current value: 2') && s.body.includes('Counter'), `checked=${s.checked}`);
await page.screenshot({ path: '/tmp/verify/en.png', fullPage: true });

const radios = await page.evaluate(() => [...document.querySelectorAll('.segmented-radio-group input')].map((i) => ({ name: i.name, type: i.type })));
check('radio inputs share a name (keyboard group works)', radios.length === 2 && radios[0].name && radios[0].name === radios[1].name, JSON.stringify(radios));

console.log(results.join('\n'));
console.log('--- console errors/warnings ---');
console.log(errors.join('\n') || '(none)');
await browser.close();

